{"carrier":{"carrier_id":"chipbench_Prob002_wildcard_medium","clean_rtl":"module TopModule(
	input clk,
	input rst_n,
	input a,
	output match
	);

	reg [8:0] a_tem;
	reg match_f;
	reg match_b;

	always @(posedge clk or negedge rst_n)
		if (!rst_n)
			begin 
				match_f <= 1'b0;
			end
		else if (a_tem[8:6] == 3'b011)
			begin
				match_f <= 1'b1;
			end
		else 
			begin	
				match_f <= 1'b0;
			end

	always @(posedge clk or negedge rst_n)
		if (!rst_n)
			begin 
				match_b <= 1'b0;
			end
		else if (a_tem[2:0] == 3'b110)
			begin
				match_b <= 1'b1;
			end
		else 
			begin	
				match_b <= 1'b0;
			end

	always @(posedge clk or negedge rst_n)
		if (!rst_n)
			begin 
				a_tem <= 9'b0;
			end
		else 
			begin
				a_tem <= {a_tem[7:0],a};
			end

	assign match = match_b && match_f;
endmodule","dependencies":{},"edit_budget":{"all_code_token_limit":65,"body_token_limit":58,"max_changed_fraction":0.4,"metric":"sum max(deleted, inserted) over token diff hunks; both limits apply","tokenizer":"verilog_source_tokens_v2_macros"},"editable_file":"rtl/sequence.sv","freeze_hash":"sha256:91bc66782458141b9a361b0c44e1e35a8965d8ae0ff68a3e3e03fa88fa6bec34","manifest_hash":"sha256:e29c6aa5381e6db36d9e23e3f0cf7df79f6c1c2b1e789e85820a9bb2d3f67fe9","parameters":{},"public_suites":{"W_bug":{"tb.sv":"module tb;
